for (i = 0; i < 3; i++) {
  d = JSON.parse(java.ajax(xGorgon(
    "new_category/front",
    [
      "update_version_code=99999",
      "distinct_style=1",
      "new_category_tab=" + i
    ].join("&")
  ))).data.category_tab_data
  cate = []
  cate.push(obj("====== " + d.tab_name + " ======", "", 1))
  d.cell_data.forEach((c) => {
    cate.push(obj(c.cell_name, js(c.atom_data[0].category_data.category_id), 1))
    for (j = 2; j < 5; j++) {
      c.atom_data.slice(1).forEach((a) => {
        dd = a.category_data
        if (dd.name.length == j) cate.push(obj(dd.name, js(dd.category_id), -1))
      })
    }
  })
  arr = cate.concat(arr)
}

